head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	let length = WebSquare.wUnit.getDomById('wq_uuid_1_contents_content1_body_pivot1_body_table').querySelectorAll('tr').length
	return length == 1;
}	

scwin.unitTest = function(){
	//init
	WebSquare.wUnit.start();

	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_contents_content1_body_pivot1_container_header_colAxisList').querySelectorAll('span')[1].click()");
	WebSquare.wUnit.addCommand("pause", "500");			
	WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('pvtFilterBox')[0].querySelectorAll('button')[1].click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('pvtFilter')[2].click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('pvtFilterBox')[0].querySelectorAll('button')[2].click()");
	WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_tab_tabs2').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_tab_tabs1').click()");
	WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");		

	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
